const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const paths={tiktok:'M14 3v12a4 4 0 1 1-4-4M14 3c0 4 3 6 6 6','arrow-up-right':'M7 17 17 7M7 7h10v10',arrow:'M4 12h15m-6-6 6 6-6 6',pin:'M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0Z M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',check:'m5 12 4 4L19 6',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18Z',compass:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM16 8l-3 5-5 3 3-5 5-3Z',shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6l-8-3Zm-4 9 3 3 5-6',chat:'M21 11a8 8 0 0 1-8 8H8l-5 3V11a9 9 0 0 1 18 0Z',whatsapp:'M20 11.6a8 8 0 0 1-11.8 7L4 20l1.4-4.1A8 8 0 1 1 20 11.6ZM9 8c0 3 2 5 5 6l1-1.5 2 1c-1 3-4 2-6 0S7 9 9 8Z',search:'M16 16l5 5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',info:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM12 11v6M12 7v1',file:'M14 2H5v20h14V7l-5-5ZM14 2v6h5M8 13h8M8 17h6',expand:'M8 3H3v5M16 3h5v5M3 16v5h5M21 16v5h-5',heart:'M12 21 3.5 12.5A5.5 5.5 0 0 1 12 5a5.5 5.5 0 0 1 8.5 7.5L12 21Z'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.arrow}"/></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('id-ID').format(n);
const wa=(topic='')=>'https://wa.me/'+SITE.whatsapp+'?text='+encodeURIComponent('Assalamu’alaikum Bu Tania, saya ingin berkonsultasi tentang perjalanan umroh atau haji bersama Samira Travel melalui Umroh Amanah Samira');
const button=(text,topic='',cls='')=>`<a class="button ${cls}" href="${wa(topic)}" target="_blank" rel="noopener">${text}${icon('arrow-up-right')}</a>`;
const link=(text,href)=>`<a class="text-link" href="${href}">${text}${icon('arrow-up-right')}</a>`;
const categories=[['semua','Semua Perjalanan'],['reguler','Ekonomi / Reguler'],['lampung','Umroh Lampung'],['vip','VIP'],['private','VVIP Private'],['plus','Umroh Plus'],['haji','Haji Plus']];
const filters=(selected='semua')=>`<div class="catalog-tabs" role="group" aria-label="Filter jenis perjalanan">${categories.map(([id,label])=>`<button class="filter ${id===selected?'active':''}" data-filter="${id}" aria-pressed="${id===selected}">${label}</button>`).join('')}</div>`;
const lampungProgram={id:SITE.departure.id,name:'Umroh Lampung 12 Hari',category:'lampung',label:'UMROH LAMPUNG',price:SITE.departure.options[0].price,priceLabel:'Mulai dari',image:SITE.departure.brochure,alt:'Brosur Umroh Lampung 12 Hari — 9 Desember 2026',location:'Lampung–Jakarta–Jeddah',description:'9 Desember 2026 · Saudia. Pilihan Safara, Safawi, dan Majol; penerbangan Lampung–Jakarta P/P termasuk.',href:'#/keberangkatan/'+SITE.departure.id};
const programs=[...SITE.packages.filter(p=>p.category==='reguler'),lampungProgram,...SITE.packages.filter(p=>p.category!=='reguler')];
const programHref=p=>p.href||'#/paket/'+p.id;
function priceMarkup(p){return p.price?`<small>${p.priceLabel} / jamaah</small><strong>Rp${money(p.price)}</strong>`:`<small>${(p.id==='umroh-vvip-private'||p.tentative)?'Harga tentatif':'Informasi harga'}</small><strong class="price-pending">${p.tentative?'Konsultasi dengan Mitra':p.id==='umroh-vvip-private'?'Konsultasi Private':p.id==='umroh-vip'?'Konsultasi dengan Mitra':p.priceLabel}</strong>`}
function card(p){return `<article class="package-card"><a class="card-main" href="${programHref(p)}" aria-label="Lihat ${p.name}"><div class="package-photo ${p.category==='lampung'?'brochure-photo':''}"><img src="${p.image}" alt="${p.alt}" loading="lazy" width="600" height="400"><span class="photo-tag ${['vip','private'].includes(p.category)?'gold':''}">${p.label}</span><span class="photo-location">${icon('pin')}${p.location}</span></div><div class="package-body"><span class="package-category">${p.label}</span><h3>${p.name}</h3><p>${p.description}</p><div class="package-bottom"><div>${priceMarkup(p)}</div><span class="arrow-circle">${icon('arrow-up-right')}</span></div><p class="card-price-note">Harga dapat berubah sewaktu-waktu.</p></div></a><div class="card-actions"><a class="card-detail" href="${programHref(p)}">Lihat Detail${icon('arrow-up-right')}</a><a class="card-whatsapp" href="${wa(p.name)}" target="_blank" rel="noopener" aria-label="Konsultasi ${p.name} melalui WhatsApp">${icon('whatsapp')}Konsultasi</a></div></article>`}
const catalogNote=()=>`<p class="catalog-note">${icon('info')}<span>Harga dapat berubah sewaktu-waktu. Jadwal, ketersediaan, hotel, dan fasilitas mengikuti penawaran yang dikonfirmasi. Foto merupakan ilustrasi destinasi dan suasana perjalanan, bukan jaminan hotel atau fasilitas tertentu.</span></p>`;
const cta=()=>`<section class="container contact-cta"><div class="cta-copy"><span class="eyebrow">AWALI DENGAN PERCAKAPAN</span><h2>Niat baik Anda,<br>kita persiapkan bersama.</h2><p>Tak perlu punya semua jawabannya sekarang. Ceritakan rencana Anda kepada Mitra.</p></div><div class="cta-action">${button('Konsultasi melalui WhatsApp','','white')}<small>Personal · Langsung dengan Mitra · Seluruh Indonesia</small></div></section>`;
const pageHero=(label,title,description='')=>`<section class="page-hero"><div class="container"><div class="breadcrumbs"><a href="#/">Beranda</a><span>/</span>${label}</div><span class="eyebrow">${label}</span><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div></section>`;
const faqItems=[['Apakah Samira Travel memiliki perizinan penyelenggaraan umroh dan haji khusus?','Situs resmi Samira Travel mencantumkan perizinan PPIU untuk perjalanan ibadah umroh dan PIHK untuk haji khusus, atas nama PT Samira Ali Wisata. Artikel resmi perusahaan juga memuat referensi PPIU 137 Tahun 2020. Informasi dan tautan sumber dapat dilihat pada bagian Perizinan Penyelenggara di halaman Tentang Mitra.'],['Apakah melayani jamaah dari luar Jakarta?','Ya. Umroh Amanah Samira melayani calon jamaah dari seluruh Indonesia. Konsultasi dapat dilakukan melalui WhatsApp. Pilihan kota dan bandara keberangkatan dikonfirmasi sesuai program yang tersedia.'],['Berapa harga Umroh Ekonomi / Reguler?','Umroh Ceria mulai Rp31 jutaan (9 hari), Rp33 jutaan (12 hari), dan Rp36 jutaan (16 hari). Safara mulai Rp36 jutaan dan Safawi mulai Rp39 jutaan. Semua harga dapat berubah sewaktu-waktu. Harga akhir mengikuti tanggal keberangkatan, pilihan kamar, ketersediaan, serta ketentuan paket. Mintalah rincian terbaru sebelum mendaftar.'],['Bagaimana mengetahui harga VIP dan VVIP Private?','Paket VIP Sukari mulai Rp50 jutaan dan Majol mulai Rp55 jutaan. Semua harga dapat berubah sewaktu-waktu. Untuk VVIP Private, harga bersifat tentatif, mengikuti kebutuhan perjalanan, jumlah peserta, serta program yang disepakati.'],['Apakah tersedia Umroh Plus Turki dan Mesir?','Umroh Plus Turki mulai dari Rp50 jutaan; harga dapat berubah sewaktu-waktu. Harga Plus Mesir bersifat tentatif dan harus dikonsultasikan terlebih dahulu kepada Mitra. Ketersediaan, destinasi yang dikunjungi, rute, harga, dan jadwal mengikuti penawaran terbaru yang akan dijelaskan Mitra.'],['Bagaimana cara mendaftar?','Pilih program yang menarik bagi Anda, lalu tekan tombol konsultasi WhatsApp. Mitra membantu menjelaskan pilihan, memeriksa ketersediaan, dan memandu persiapan pendaftaran hingga keberangkatan.'],['Bagaimana proses pembayaran yang benar?','Ikuti instruksi pembayaran resmi Samira Travel dan konfirmasikan detailnya saat pendaftaran. Pembayaran tidak dititipkan kepada rekening pribadi mitra. Simpan bukti transaksi dan konfirmasi pendaftaran.']];
const faqs=(limit=faqItems.length)=>`<div class="faq-list">${faqItems.slice(0,limit).map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div>`;
function story(){return `<div class="story-grid"><div class="story-visual"><img class="mitra-profile-photo" src="assets/tania-tombeng-profil.jpg" alt="Foto profil Tania Tombeng, Mitra Samira Travel" loading="lazy" width="722" height="1599"><div class="story-caption"><span class="monogram">TT</span><b>Tania Tombeng</b><small>Mitra Samira Travel · Riwayat kompetensi Tour Leader</small></div></div><div class="story-copy"><span class="eyebrow">ADA MITRA DI SETIAP LANGKAH</span><h2>Perjalanan besar.<br><em>Pendampingan personal.</em></h2><p>Di balik setiap perjalanan ke Baitullah, ada harapan, pertanyaan, dan persiapan yang berbeda. Kami percaya semuanya layak didengarkan.</p><p>Bersama Tania Tombeng, mitra Samira Travel yang pernah memperoleh sertifikat kompetensi BNSP bidang pemimpin perjalanan wisata, rencanakan ibadah dengan informasi yang jelas dan bantuan sejak awal.</p><ul class="story-points"><li>${icon('check')}Konsultasi sesuai kebutuhan Anda dan keluarga</li><li>${icon('check')}Bantuan pendaftaran dan persiapan keberangkatan</li><li>${icon('check')}Melayani calon jamaah dari seluruh Indonesia</li></ul>${link('Kenali Mitra Anda','#/tentang')}</div></div>`}
function journalCards(){return `<div class="journal-grid">${SITE.articles.map((a,i)=>`<a class="journal-card" href="#/artikel/${a.id}"><div class="journal-photo"><img src="${a.image}" alt="Suasana Tanah Suci" loading="lazy" width="600" height="400"></div><span class="eyebrow">${a.tag}</span><h3>${a.title}</h3><p>${a.desc}</p><div class="journal-bottom"><span>CATATAN PERJALANAN · 0${i+1}</span>${icon('arrow-up-right')}</div></a>`).join('')}</div>`}
function awards(){return `<section class="awards-section"><div class="container section"><div class="section-top"><div><span class="eyebrow">PENCAPAIAN PT SAMIRA ALI WISATA</span><h2>Tiga rekor MURI.<br><em>Jejak pelayanan Samira.</em></h2><p>Penghargaan yang diraih Samira Travel atas pencapaian perjalanan ibadah dan kebersamaan jamaah.</p></div><img class="muri-badges" src="assets/rekor-muri-samira.png" alt="Tiga penghargaan MURI Samira: jamaah terbanyak masa pandemi, talbiyah peserta terbanyak, dan jamaah terbanyak tahun 2024" loading="lazy" width="568" height="164"></div><div class="awards-grid">${SITE.awards.map((a,i)=>`<article class="award-card"><span class="award-no">0${i+1} / REKOR MURI</span><h3>${a.title}</h3><p>${a.description}</p><a class="text-link" href="${a.source}" target="_blank" rel="noopener">Sumber resmi Samira${icon('arrow-up-right')}</a></article>`).join('')}</div><p class="award-attribution">Penghargaan atas nama PT Samira Ali Wisata (Samira Travel). Informasi dan materi penghargaan merujuk pada situs resmi perusahaan.</p></div></section>`}
function departureHotels(index=0){const o=SITE.departure.options[index],p=SITE.packages.find(p=>p.id===o.packageId);return `<div class="hotel-grid">${[['makkah','Makkah'],['madinah','Madinah']].map(([key,city])=>`<article class="hotel-panel"><div class="hotel-city">${icon('pin')}<div><span>PILIHAN HOTEL ${o.name.toUpperCase()}</span><h3>${city}</h3></div></div><ul>${p.hotels[key].map(h=>`<li>${icon('check')}${h}</li>`).join('')}</ul><span class="hotel-equivalent">Atau hotel setaraf</span></article>`).join('')}</div>`}
function departurePage(id){const d=SITE.departure;if(id&&id!==d.id)return notFound();return pageHero('Keberangkatan Terjadwal','Umroh Lampung<br><em>12 Hari — 9 Desember 2026.</em>','Lampung–Jeddah via Jakarta. Penerbangan internasional Jakarta–Jeddah menggunakan Saudia, tanpa transit sesuai brosur.')+`<section class="container section"><div class="detail-grid"><div><button class="departure-brochure" data-lightbox="${d.brochure}" data-caption="Brosur Umroh Lampung 12 Hari · 9 Desember 2026 · Harga dapat berubah sewaktu-waktu" aria-label="Perbesar brosur Umroh Lampung"><img class="brochure" src="${d.brochure}" alt="Brosur Umroh Lampung 12 hari beserta harga Safara, Safawi dan Majol"></button><p class="catalog-note">Klik brosur untuk melihat gambar utuh.</p><a class="text-link" href="${d.brochure}" download>Unduh brosur${icon('file')}</a></div><div class="detail-copy"><span class="eyebrow">9 DESEMBER 2026 · SAUDIA · 12 HARI</span><h2>Pilih paket<br><em>perjalanan Anda.</em></h2><p>Penerbangan pulang-pergi Lampung–Jakarta termasuk dalam program yang Anda konsultasikan. Pilihan hotel mengikuti paket.</p><div class="variant-select departure-options" role="group" aria-label="Pilihan paket keberangkatan Lampung">${d.options.map((o,i)=>`<button class="variant ${i===0?'active':''}" data-departure-option="${i}" aria-pressed="${i===0}"><b>${o.name}</b><small>Rp${money(o.price)}</small></button>`).join('')}</div><div class="detail-price"><small id="departure-label">Estimasi Paket Safara / jamaah</small><strong id="departure-price">Rp${money(d.options[0].price)}</strong><p class="price-caution">Harga dapat berubah sewaktu-waktu. Konfirmasikan harga akhir, kursi, jadwal, hotel dan rincian layanan dengan Mitra sebelum mendaftar.</p></div>${button('Konsultasikan Keberangkatan Ini','','full')}<div class="detail-usps"><span>2 kali umroh</span><span>2 Jumat sesuai program</span><span>Lampung–Jakarta P/P</span></div><div class="facility-heading facility-second"><h2>Fasilitas program.</h2></div><ul class="discuss-list">${d.facilities.map(t=>`<li>${icon('check')}<span>${t}</span></li>`).join('')}</ul><details class="facility-excluded" open style="margin-top:25px"><summary>Harga belum termasuk</summary><ul>${d.excluded.map(t=>`<li>${t}</li>`).join('')}</ul></details><p class="hotel-note">Kunjungan, dua kali umroh, dua Jumat, dan akses Raudhah mengikuti pelaksanaan program, izin serta kondisi operasional.</p></div></div><div class="package-facilities"><span class="eyebrow">AKOMODASI SESUAI PILIHAN PAKET</span><h2>Pilihan hotel.</h2><div id="departure-hotels">${departureHotels()}</div><p class="hotel-note">Hotel atau setaraf mengikuti ketersediaan dan konfirmasi program. Harga di atas khusus keberangkatan ini dan berbeda dari estimasi umum paket.</p></div></section>`+cta()}
function samiraValues(){return `<section class="container section samira-values"><div class="section-top"><div><span class="eyebrow">SEMANGAT LAYANAN SAMIRA</span><h2>Murah. <em>Mudah.</em> Mantap.</h2><p>Pilihan perjalanan yang sesuai kebutuhan, proses yang dibantu dengan jelas, dan persiapan ibadah yang terarah.</p></div><span class="samira-mark" aria-hidden="true">3M</span></div><div class="samira-values-grid">${[['01','Murah','Pilihan sesuai anggaran','Paket umroh mulai Rp31 jutaan, dengan pilihan reguler hingga private. Harga dapat berubah sewaktu-waktu; rincian akhir dikonfirmasi bersama Mitra.','compass'],['02','Mudah','Dekat dalam proses','Konsultasi melalui WhatsApp dari seluruh Indonesia. Mitra membantu memahami program, menyiapkan dokumen, dan memandu proses pendaftaran.','chat'],['03','Mantap','Lebih siap melangkah','Kenali pilihan hotel, fasilitas, dan kebutuhan perjalanan sebelum menentukan program. Persiapan yang jelas membantu Anda melangkah lebih tenang.','shield']].map(([n,t,h,p,i])=>`<article class="samira-value"><div class="samira-value-top"><span>${n} / SAMIRA</span>${icon(i)}</div><h3>${t}</h3><strong>${h}</strong><p>${p}</p></article>`).join('')}</div></section>`}
function samiraPermits(){const c=SITE.samiraProfile;return `<section class="samira-permits"><div class="container section"><div class="section-top"><div><span class="eyebrow">PERIZINAN PENYELENGGARA</span><h2>Kenali penyelenggaranya.<br><em>Rencanakan dengan tenang.</em></h2><p>Samira Travel berada di bawah ${c.company}. Situs resmi perusahaan mencantumkan izin Kementerian Agama RI untuk penyelenggaraan umroh dan haji khusus.</p></div><div class="permit-company">${icon('shield')}<span>PENYELENGGARA PERJALANAN<b>${c.company}</b><small>Samira Travel</small></span></div></div><div class="permit-grid">${c.permits.map(p=>`<article class="permit-card"><span class="permit-code">${icon('shield')}${p.code}</span><h3>${p.name}</h3><p>${p.description}</p><p class="permit-reference">${p.reference}</p></article>`).join('')}</div><div class="permit-bottom"><div><p>Perizinan ini merupakan perizinan perusahaan penyelenggara ${c.company}. Umroh Amanah Samira membantu konsultasi dan pendaftaran melalui Mitra.</p><small>Informasi merujuk sumber resmi Samira · Ditinjau ${c.checked}.</small></div><div class="permit-source-links"><a class="text-link" href="${c.source}" target="_blank" rel="noopener">Situs resmi Samira${icon('arrow-up-right')}</a><a class="text-link" href="${c.permitSource}" target="_blank" rel="noopener">Referensi izin PPIU${icon('arrow-up-right')}</a></div></div></div></section>`}
function home(){return `<section class="hero"><img class="hero-bg" src="assets/masjidil-haram.jpg" alt="Panorama Masjidil Haram dan Ka’bah" fetchpriority="high" width="2060" height="1368"><div class="container"><span class="eyebrow">UMROH AMANAH SAMIRA · SELURUH INDONESIA</span><h1>Perjalanan suci.<br>Dipersiapkan<br><em>sepenuh hati.</em></h1><p class="hero-description">Ada rindu yang hanya terjawab di Tanah Suci. Temukan pilihan perjalanan Anda, dengan bantuan personal dari Mitra Samira Travel.</p><div class="hero-actions"><a class="button" href="#/paket">Temukan Perjalanan Anda${icon('arrow-up-right')}</a>${button('Bicara dengan Mitra','','glass')}</div><div class="hero-chip"><span>✦</span>Murah · Mudah · Mantap</div></div><span class="hero-side">MAKKAH · SAUDI ARABIA</span><div class="hero-bottom">“Setiap niat baik, sebuah awal yang indah.”<small>YOUR JOURNEY TO THE HOLY LAND</small></div></section><div class="container"><form class="journey-picker" id="journey-picker"><div class="picker-intro"><b>Mulai dari niat Anda.</b><small>Kami bantu menemukan pilihannya.</small></div><div class="field"><label for="journey-type">SAYA INGIN MENJELAJAHI</label><select id="journey-type"><option value="semua">Semua perjalanan</option>${programs.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select></div><div class="field picker-service"><span class="picker-label">CAKUPAN LAYANAN</span><b>Seluruh Indonesia</b><small>Konsultasi online bersama Mitra</small></div><button class="button" type="submit">Lihat Pilihan${icon('arrow')}</button></form><div class="brand-promises"><span>${icon('globe')}Melayani seluruh Indonesia</span><span>${icon('chat')}Konsultasi langsung dengan Mitra</span><span>${icon('shield')}Penyelenggara PPIU & PIHK</span><span>${icon('heart')}Persiapan dengan sepenuh hati</span></div></div>${samiraValues()}<section class="container section"><div class="section-top"><div><span class="eyebrow">PILIHAN PERJALANAN ANDA</span><h2>Berbeda rencana.<br>Satu <em>tujuan yang dirindukan.</em></h2><p>Dari perjalanan reguler hingga private, temukan program yang selaras dengan kebutuhan dan harapan Anda.</p></div>${link('Jelajahi semua program','#/paket')}</div>${filters()}<div class="package-grid" id="package-results">${programs.map(card).join('')}</div>${catalogNote()}</section>${awards()}${samiraPermits()}<section class="story-section"><div class="container section">${story()}</div></section><section class="container section"><div class="section-top"><div><span class="eyebrow">DARI NIAT MENUJU KEBERANGKATAN</span><h2>Langkah pertama,<br>tak perlu <em>sendirian.</em></h2></div><p>Persiapan yang baik dimulai dari percakapan yang terbuka. Mitra membantu Anda memahami prosesnya.</p></div><div class="journey-steps">${[['Ceritakan rencana','Sampaikan waktu, anggaran, dan kebutuhan perjalanan Anda.'],['Temukan pilihan','Pelajari program, fasilitas, dan rincian penawaran yang tersedia.'],['Siapkan pendaftaran','Dapatkan panduan dokumen serta pembayaran resmi.'],['Bersiap berangkat','Lengkapi persiapan dan ikuti arahan keberangkatan.']].map(([t,d],i)=>`<div><div class="step-number">0${i+1}</div><h3>${t}</h3><p>${d}</p></div>`).join('')}</div></section><section class="destination-banner"><div class="destination-photo"><img src="assets/turki.jpg" alt="Masjid Ortaköy dan Selat Bosphorus, Istanbul" loading="lazy" width="1000" height="700"><span>Istanbul, a story beyond the journey.</span></div><div class="destination-copy"><span class="eyebrow">UMROH PLUS</span><h2>Memenuhi panggilan.<br>Menjelajahi <em style="color:#a3d9fc">jejak peradaban.</em></h2><p>Lengkapi perjalanan ibadah Anda dengan inspirasi destinasi Turki atau Mesir. Konsultasikan pilihan program dan rangkaian perjalanan yang tersedia.</p><div class="destination-links">${link('Jelajahi Turki','#/paket/umroh-plus-turki')}${link('Jelajahi Mesir','#/paket/umroh-plus-mesir')}</div></div></section>${documentationPreview()}${testimonialsPreview()}<section class="journal-section"><div class="container section"><div class="section-top"><div><span class="eyebrow">JURNAL & INSPIRASI</span><h2>Bekal kecil untuk<br>perjalanan <em>yang berarti.</em></h2></div>${link('Baca semua catatan','#/artikel')}</div>${journalCards()}</div></section><section class="container section faq-layout"><div class="faq-intro"><span class="eyebrow">SEBELUM ANDA MELANGKAH</span><h2>Ada pertanyaan?<br>Kami <em>mendengarkan.</em></h2><p>Temukan informasi awal seputar pilihan perjalanan, harga, dan proses pendaftaran.</p>${link('Semua pertanyaan','#/faq')}</div>${faqs(5)}</section>${cta()}`}
let activeCategory='semua',searchTerm='';
function packages(category='semua'){activeCategory=categories.some(x=>x[0]===category)?category:'semua';searchTerm='';return pageHero('Pilihan Perjalanan','Temukan perjalanan<br>yang <em>Anda rindukan.</em>','Pilihan paket perjalanan untuk kebutuhan yang berbeda. Pilih perjalanan Anda, lalu bicarakan detailnya bersama Mitra.')+`<section class="container section"><div class="catalog-toolbar">${filters(activeCategory)}<label class="catalog-search">${icon('search')}<input id="package-search" type="search" placeholder="Cari program perjalanan…" aria-label="Cari program perjalanan"></label></div><div class="catalog-summary"><span id="result-count" aria-live="polite"></span><span>Melayani seluruh Indonesia</span></div><div id="package-results" class="package-grid"></div>${catalogNote()}<div class="consult-strip"><div><h3>Belum menemukan pilihan Anda?</h3><p>Ceritakan rencana perjalanan, Mitra siap membantu menjelaskan pilihannya.</p></div>${button('Bantu Saya Memilih')}</div></section>`+cta()}
function updatePackages(){const matches=programs.filter(p=>(activeCategory==='semua'||p.category===activeCategory)&&(p.name+' '+p.description).toLowerCase().includes(searchTerm.toLowerCase()));const r=$('#package-results');if(!r)return;r.innerHTML=matches.length?matches.map(card).join(''):`<div class="no-results"><h3>Belum ada program yang cocok.</h3><p>Coba kata kunci lain atau lihat semua program.</p><button class="button" data-reset>Reset Pencarian${icon('arrow')}</button></div>`;const n=$('#result-count');if(n)n.textContent=`${matches.length} pilihan perjalanan`;$$('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===activeCategory);b.setAttribute('aria-pressed',String(b.dataset.filter===activeCategory))});initVisualEffects()}
function packageFacilities(p){if(!p.hotels)return '';return `<section class="package-facilities"><div class="facility-heading"><span class="eyebrow">REFERENSI AKOMODASI SAMIRA TRAVEL</span><h2>Pilihan hotel ${p.name.replace('Paket ','')}.</h2><p>Pilihan hotel di Makkah dan Madinah untuk membantu Anda mengenali akomodasi program.</p></div><div class="hotel-grid">${[['makkah','Makkah','Dekat dengan tujuan ibadah Anda'],['madinah','Madinah','Menikmati waktu di Kota Nabi']].map(([key,city,desc])=>`<article class="hotel-panel"><div class="hotel-city">${icon('pin')}<div><span>AKOMODASI DI</span><h3>${city}</h3></div></div><ul>${p.hotels[key].map(name=>`<li>${icon('check')}${name}</li>`).join('')}</ul><span class="hotel-equivalent">Atau hotel setaraf</span></article>`).join('')}</div><p class="hotel-note">Pilihan hotel mengikuti program, jadwal dan ketersediaan. Nama di atas merupakan alternatif hotel atau setaraf; hotel yang digunakan dikonfirmasi Mitra sebelum pendaftaran. Referensi Safara di Madinah juga mengacu pada brosur Samira.</p><a class="text-link" href="${SITE.facilities.hotelSource}" target="_blank" rel="noopener">Referensi hotel Samira Travel${icon('arrow-up-right')}</a><div class="facility-heading facility-second"><span class="eyebrow">BEKAL PERJALANAN ANDA</span><h2>Fasilitas sesuai program.</h2><p>Ringkasan fasilitas umum umroh Samira Travel. Rincian akhir mengikuti penawaran paket dan tanggal keberangkatan Anda.</p></div><ul class="facility-grid">${SITE.facilities.included.map(t=>`<li>${icon('check')}<span>${t}</span></li>`).join('')}</ul><details class="facility-excluded"><summary>Komponen yang belum termasuk</summary><ul>${SITE.facilities.excluded.map(t=>`<li>${t}</li>`).join('')}</ul></details><p class="hotel-note">Harga semua perjalanan serta biaya tambahan dapat berubah sewaktu-waktu. Batas bagasi, jumlah manasik, dan rincian layanan dikonfirmasi mengikuti program yang dipilih.</p><a class="text-link" href="${SITE.facilities.source}" target="_blank" rel="noopener">Syarat dan fasilitas resmi Samira${icon('arrow-up-right')}</a></section>`}
function ceriaDetails(p){return `<section class="ceria-details"><div><span class="eyebrow">SESUAI BROSUR UMROH CERIA</span><h2>Perjalanan dari Jakarta.</h2><p>Rute Jakarta–Jeddah bersama Saudia. Brosur memuat jadwal ${p.brochurePeriod}. Tanggal yang masih tersedia, pilihan hotel dan rincian fasilitas dikonfirmasi bersama Mitra sebelum mendaftar.</p><p class="hotel-note">Pilihan akomodasi pada brosur meliputi Safara, Safawi, Sukari, dan Majol. Harga awal Umroh Ceria bukan jaminan seluruh pilihan hotel; minta rincian paket dan penawaran yang sesuai.</p></div><aside class="detail-note"><h3>Tambahan pilihan perjalanan</h3><p>${p.addOn}</p><p class="price-caution">Harga paket dan tambahan dapat berubah sewaktu-waktu. Semua pembayaran mengikuti instruksi resmi PT Samira Ali Wisata.</p><a class="text-link" href="${p.brochure}" download>Unduh brosur${icon('file')}</a></aside></section>`}
function detail(id){const p=SITE.packages.find(p=>p.id===id);if(!p)return notFound();return `<section class="container section detail-hero"><div class="breadcrumbs"><a href="#/">Beranda</a><span>/</span><a href="#/paket">Pilihan Perjalanan</a><span>/</span>${p.name}</div><div class="detail-grid"><div><div class="detail-photo"><img src="${p.image}" alt="${p.alt}" fetchpriority="high" width="900" height="1000"><p>${p.location}<small>ILUSTRASI SUASANA PERJALANAN</small></p></div>${p.brochure?`<button class="brochure-link" data-lightbox="${p.brochure}" data-caption="${esc(p.brochureTitle)} · Harga dan jadwal perlu dikonfirmasi kembali">${icon('file')}<span>Lihat brosur Umroh Ceria<small>${p.brochureDescription} · Klik untuk memperbesar</small></span>${icon('expand')}</button>`:''}</div><div class="detail-copy"><span class="eyebrow">${p.label}</span><h1>${p.name}</h1><p>${p.intro}</p><div class="detail-price"><small id="detail-price-label">${p.price?'Mulai dari / jamaah':p.priceLabel}</small><strong id="detail-price" class="${p.price?'':'pending'}">${p.price?'Rp'+money(p.price):p.id==='umroh-vvip-private'?'Sesuai kebutuhan Anda':'Konsultasi dengan Mitra'}</strong>${p.variants?`<div class="variant-select package-options" role="group" aria-label="Pilihan paket ${p.name}">${p.variants.map((v,i)=>`<button class="variant ${i===0?'active':''}" data-package-option="${v.name}" data-price="${v.price}" data-program="${p.name}" aria-pressed="${i===0}"><b>Paket ${v.name}</b><small>Mulai Rp${v.price/1000000} jutaan</small></button>`).join('')}</div>`:''}<p class="price-caution">Harga semua perjalanan dapat berubah sewaktu-waktu. ${p.price?'Harga mulai dari bersifat estimasi. Konfirmasikan harga akhir, jadwal, pilihan kamar dan fasilitas sebelum mendaftar.':p.tentative?'Harga tentatif. Konsultasikan terlebih dahulu dengan Mitra melalui WhatsApp untuk memperoleh penawaran terbaru.':p.id==='umroh-vvip-private'?'Harga tentatif. Konsultasikan rencana private Anda dengan Mitra melalui WhatsApp.':'Nominal harga belum ditampilkan. Hubungi Mitra untuk penawaran terbaru sesuai program yang tersedia.'}</p></div><a id="detail-wa" class="button full" href="${wa(p.name+(p.variants?' — Paket '+p.variants[0].name:''))}" target="_blank" rel="noopener">${p.tentative?'Konsultasikan Harga Tentatif':p.category==='private'?'Konsultasi Perjalanan Private':'Tanyakan Program Ini'}${icon('whatsapp')}</a><div class="detail-usps">${p.highlights.map(x=>`<span>${x}</span>`).join('')}</div></div></div>${p.brochure?ceriaDetails(p):''}${packageFacilities(p)}<div class="detail-info"><div><span class="eyebrow">SEBELUM MENENTUKAN PILIHAN</span><h2>Detail yang perlu<br>kita bicarakan.</h2><ul class="discuss-list">${p.discuss.map(x=>`<li>${icon('check')}${x}</li>`).join('')}</ul></div><aside class="detail-note"><h3>Informasi yang jelas,<br>keputusan lebih tenang.</h3><p>Durasi, akomodasi, rute, fasilitas, dan ketersediaan mengikuti rincian penawaran yang dikonfirmasi. Foto pada halaman ini merupakan ilustrasi.</p><p>Mitra siap membantu calon jamaah dari seluruh Indonesia, dari konsultasi awal hingga persiapan keberangkatan.</p>${link('Pertanyaan seputar pendaftaran','#/faq')}</aside></div></section><section class="container section" style="padding-top:0"><div class="section-top"><div><span class="eyebrow">PILIHAN LAIN UNTUK ANDA</span><h2>Temukan kemungkinan <em>lainnya.</em></h2></div>${link('Semua program','#/paket')}</div><div class="package-grid">${SITE.packages.filter(x=>x.id!==p.id).sort((a,b)=>Number(b.category===p.category)-Number(a.category===p.category)).slice(0,3).map(card).join('')}</div></section>`+cta()}
function certificate(){return `<section class="certificate-section"><div class="container section certificate-grid"><div class="certificate-visual"><button type="button" class="certificate-photo" data-lightbox="assets/sertifikat-bnsp-tour-leader.png" data-caption="Sertifikat Kompetensi BNSP · Ratanya Tombeng · Pemimpin Perjalanan Wisata (Tour Leader) · Terbit 5 Agustus 2022, masa berlaku pada dokumen 3 tahun" aria-label="Perbesar sertifikat kompetensi BNSP Tour Leader"><img src="assets/sertifikat-bnsp-tour-leader.png" alt="Sertifikat kompetensi BNSP atas nama Ratanya Tombeng di bidang Pemimpin Perjalanan Wisata, diterbitkan 5 Agustus 2022 dengan masa berlaku 3 tahun" loading="lazy" width="861" height="1226"><span>${icon('expand')}Klik untuk melihat dokumen utuh</span></button></div><div class="certificate-copy"><span class="eyebrow">RIWAYAT KOMPETENSI MITRA</span><h2>Bekal kompetensi.<br><em>Pendampingan sepenuh hati.</em></h2><p>Sertifikat kompetensi bidang Pemimpin Perjalanan Wisata (Tour Leader) menjadi bagian dari latar belakang Mitra dalam membantu persiapan dan pendampingan perjalanan Anda.</p><dl class="certificate-facts"><div><dt>Bidang kompetensi</dt><dd>Pemimpin Perjalanan Wisata<br><span>Tour Leader</span></dd></div><div><dt>Nama pada sertifikat</dt><dd>Ratanya Tombeng</dd></div><div><dt>Lembaga sertifikasi</dt><dd>LSP Pramindo · BNSP</dd></div><div><dt>Tanggal terbit</dt><dd>5 Agustus 2022 · Bekasi</dd></div></dl><p class="certificate-validity">Masa berlaku yang tercantum pada dokumen adalah 3 tahun sejak penerbitan. Dokumen ini ditampilkan sebagai riwayat kompetensi periode 2022–2025.</p><button type="button" class="button outline" data-lightbox="assets/sertifikat-bnsp-tour-leader.png" data-caption="Sertifikat Kompetensi BNSP · Ratanya Tombeng · Tour Leader · Terbit 5 Agustus 2022, berlaku 3 tahun">Lihat Sertifikat${icon('expand')}</button></div></div></section>`}
function about(){return pageHero('Tentang Mitra','Dekat dalam percakapan.<br><em>Sepenuh hati mendampingi.</em>','Kenali Tania Tombeng, mitra Samira Travel yang membantu persiapan perjalanan ibadah Anda.')+`<section class="container section">${story()}</section>${samiraValues()}${samiraPermits()}${certificate()}${awards()}<section class="story-section"><div class="container section service-grid"><div><span class="eyebrow">DI MANA PUN ANDA BERADA</span><h2>Melayani<br><em>seluruh Indonesia.</em></h2></div><div><p>Konsultasi perjalanan tak harus dimulai dari kunjungan langsung. Melalui WhatsApp, Mitra siap membantu Anda memahami pilihan program dan menyiapkan langkah pendaftaran.</p><p>Kota dan bandara keberangkatan disesuaikan dengan program yang tersedia. Sampaikan domisili serta kebutuhan Anda saat berkonsultasi.</p><div class="service-tags"><span>Konsultasi personal</span><span>Panduan pendaftaran</span><span>Persiapan keberangkatan</span></div></div></div></section>`+cta()}
const galleryImages=[['assets/kaaba.jpg','Ka’bah, Makkah','Visual referensi Samira Travel'],['assets/masjidil-haram.jpg','Masjidil Haram','Foto suasana destinasi · Shahbaz Hussain / Pexels'],['assets/madinah.jpg','Masjid Nabawi, Madinah','Visual referensi Samira Travel'],['assets/turki.jpg','Istanbul, Turki','Danielle Barnes / Unsplash'],['assets/mesir.jpg','Giza, Mesir','2H Media / Unsplash'],['assets/suite.jpg','Inspirasi kenyamanan perjalanan','Ilustrasi hotel · Fasilitas mengikuti program']];
function documentationItem(photo,index){return `<figure class="documentation-item ${photo.portrait?'portrait':''}"><button type="button" data-lightbox="${photo.src}" data-caption="${esc(photo.title+' · Dokumentasi jamaah')}" aria-label="Perbesar foto: ${photo.title}"><img src="${photo.src}" alt="${photo.alt}" loading="lazy" width="${photo.portrait?721:1599}" height="${photo.portrait?1600:722}"><span>${icon('expand')}</span></button><figcaption><small>DOKUMENTASI ${String(index+1).padStart(2,'0')}</small><span>${photo.title}</span></figcaption></figure>`}
function documentationPreview(){return `<section class="documentation-section"><div class="container section"><div class="section-top"><div><span class="eyebrow">DOKUMENTASI PERJALANAN JAMAAH</span><h2>Momen yang tersimpan.<br><em>Kenangan yang berarti.</em></h2><p>Dari persiapan, perjalanan bersama, hingga kebersamaan di Tanah Suci.</p></div>${link('Lihat semua dokumentasi','#/galeri')}</div><div class="documentation-preview">${[3,5,8].map(i=>documentationItem(SITE.documentation[i],i)).join('')}</div></div></section>`}
function videoDocumentation(){return `<section class="video-documentation" aria-labelledby="video-heading"><div class="section-top"><div><span class="eyebrow">VIDEO PERJALANAN JAMAAH</span><h2 id="video-heading">Cerita yang hidup.<br><em>Momen yang dekat.</em></h2><p>Putar video untuk melihat momen perjalanan bersama. Gunakan kontrol video untuk mengatur suara atau membuka layar penuh.</p></div><span class="video-count">${SITE.videos.length} video dokumentasi</span></div><div class="video-grid">${SITE.videos.map((v,i)=>`<figure class="video-card"><div class="video-frame"><video controls playsinline preload="none" poster="${v.poster}" aria-label="${esc(v.title)}"><source src="${v.src}" type="video/mp4">Browser Anda belum mendukung pemutar video. <a href="${v.src}">Buka video dokumentasi</a>.</video></div><figcaption><span class="video-number">VIDEO ${String(i+1).padStart(2,'0')} · ${v.duration}</span><h3>${v.title}</h3><p>${v.caption}</p></figcaption></figure>`).join('')}</div></section>`}
function youtubePreview(t){return `<button type="button" class="youtube-preview" data-youtube="${t.id}" aria-label="Putar ${esc(t.title)}"><img src="https://i.ytimg.com/vi/${t.id}/hqdefault.jpg" alt="Pratinjau ${esc(t.title)}" loading="lazy" width="480" height="360"><span class="youtube-shade"></span><span class="youtube-play" aria-hidden="true">▶</span><span class="youtube-play-label">Putar video</span></button>`}
function testimonyCard(t,featured=false){return `<article class="testimony-card ${featured?'testimony-featured':''}"><div class="youtube-frame ${t.shorts?'youtube-short':''}" data-youtube-frame="${t.id}">${youtubePreview(t)}</div><div class="testimony-copy"><span class="eyebrow">${t.shorts?'CERITA SINGKAT JAMAAH':'CERITA PILIHAN · SAMIRA TRAVEL'}</span><h${featured?'2':'3'}>${esc(t.title)}</h${featured?'2':'3'}><p class="testimony-source">Dibagikan oleh <a href="${esc(t.authorUrl)}" target="_blank" rel="noopener">${esc(t.author)}</a></p><a class="text-link" href="${t.url}" target="_blank" rel="noopener">Tonton di YouTube${icon('arrow-up-right')}</a></div></article>`}
function testimonialsPage(){return pageHero('Cerita Jamaah','Dari perjalanan mereka.<br><em>Untuk menguatkan niat Anda.</em>','Dengarkan pengalaman jamaah Samira Travel melalui video yang mereka bagikan. Pilih cerita yang ingin Anda tonton.')+`<section class="container section testimonials-section">${testimonyCard(SITE.testimonials[0],true)}<div class="section-top testimonials-heading"><div><span class="eyebrow">CERITA LAIN DARI JAMAAH</span><h2>Singkat ceritanya.<br><em>Berarti pengalamannya.</em></h2></div><span class="video-count">3 video Shorts</span></div><div class="testimony-shorts-grid">${SITE.testimonials.slice(1).map(t=>testimonyCard(t)).join('')}</div><div class="testimony-follow"><p>Ingin melihat momen perjalanan lainnya?</p>${link('Jelajahi foto & video jamaah','#/galeri')}</div></section>`+cta()}
function testimonialsPreview(){return `<section class="container testimony-invite"><div><span class="eyebrow">CERITA JAMAAH SAMIRA TRAVEL</span><h2>Pengalaman mereka.<br><em>Inspirasi untuk langkah Anda.</em></h2><p>Dengarkan cerita jamaah melalui empat video testimoni pilihan.</p></div><a class="button" href="#/testimoni">Dengarkan Cerita Jamaah${icon('arrow-up-right')}</a></section>`}
function gallery(){return pageHero('Dokumentasi Jamaah','Perjalanan bersama.<br><em>Kenangan sepenuh hati.</em>','Foto dan video kebersamaan dalam perjalanan serta suasana ibadah jamaah. Putar video atau klik foto untuk melihat momen secara utuh.')+`<section class="container section">${videoDocumentation()}<div class="documentation-intro"><span class="eyebrow">MOMEN PERJALANAN</span><span>${SITE.documentation.length} foto dokumentasi</span></div><div class="documentation-grid">${SITE.documentation.map(documentationItem).join('')}</div><details class="destination-references"><summary>Jelajahi inspirasi destinasi</summary><p>Foto destinasi di bawah merupakan referensi suasana perjalanan.</p><div class="gallery-grid">${galleryImages.map(([src,title,credit])=>`<figure class="gallery-item"><button data-lightbox="${src}" data-caption="${esc(title+' · '+credit)}" aria-label="Perbesar gambar ${title}"><img src="${src}" alt="${title}" loading="lazy" width="600" height="450"><span>${icon('expand')}</span></button><figcaption>${title}<br><span>${credit}</span></figcaption></figure>`).join('')}</div></details></section>`+cta()}
function article(id){const a=SITE.articles.find(a=>a.id===id);if(!a)return notFound();return pageHero(a.tag,a.title,a.desc)+`<article class="container section narrow prose"><div class="article-meta"><span>UMROH AMANAH SAMIRA</span><span>·</span><span>CATATAN PERSIAPAN</span></div><img class="article-cover" src="${a.image}" alt="Suasana Tanah Suci">${a.body.map(x=>`<p>${x}</p>`).join('')}<p class="catalog-note">Informasi awal untuk membantu persiapan. Detail program dan persyaratan dikonfirmasi saat konsultasi.</p>${link('Kembali ke jurnal','#/artikel')}</article>`+cta()}
function contact(){return pageHero('Hubungi Kami','Niat baik Anda.<br><em>Awal percakapan kita.</em>','Konsultasi pilihan umroh dan haji bersama Mitra, untuk calon jamaah dari seluruh Indonesia.')+`<section class="container section contact-grid"><div class="contact-card"><span class="eyebrow">KONSULTASI PERSONAL</span><h2>Tania Tombeng</h2><p>Mitra Samira Travel<br>Riwayat kompetensi BNSP bidang Tour Leader</p><a class="contact-number social-contact" href="${wa()}" target="_blank" rel="noopener">${icon('whatsapp')}<span>0823-1080-8355</span></a>${button('Mulai Percakapan dengan Mitra')}<div><a class="text-link social-contact" href="https://www.tiktok.com/@tania.tombeng" target="_blank" rel="noopener">${icon('tiktok')}<span>@tania.tombeng</span>${icon('arrow-up-right')}</a></div></div><div class="contact-card"><span class="eyebrow">KANTOR PUSAT SAMIRA TRAVEL</span><h2>Temui kami<br>di Jakarta.</h2><p>Jl. Malaka Merah No. 7/6, Pondok Kopi,<br>Duren Sawit, Jakarta Timur 13460.</p><p>Hubungi Mitra terlebih dahulu untuk merencanakan konsultasi di kantor. Konsultasi online tersedia untuk seluruh Indonesia.</p><a class="button outline" href="https://www.google.com/maps/search/?api=1&query=Samira+Travel+Kantor+Pusat+Pondok+Kopi" target="_blank" rel="noopener">Lihat Google Maps${icon('arrow-up-right')}</a></div></section>`}
const notFound=()=>pageHero('Halaman Tidak Ditemukan','Mari kembali<br>ke awal perjalanan.','Halaman yang Anda cari belum tersedia.')+`<section class="container section"><a class="button" href="#/">Kembali ke Beranda${icon('arrow')}</a></section>`;
function route(){const raw=location.hash.replace(/^#\/?/,'');const [pathname,query='']=raw.split('?');const [page='',id]=pathname.split('/');return {page,id,query:new URLSearchParams(query)}}
function render(){const {page,id,query}=route();let html,title='Perjalanan Suci, Sepenuh Hati';activeCategory='semua';searchTerm='';switch(page){case '':html=home();break;case 'paket':{const aliases={'umroh-9-hari':'umroh-ceria-9-hari','umroh-12-hari':'umroh-ceria-12-hari','umroh-16-hari':'umroh-ceria-16-hari','umroh-reguler':'paket-safara','umroh-vip':'paket-sukari'};html=id?detail(aliases[id]||id):packages(query.get('jenis')||'semua');title=id?SITE.packages.find(p=>p.id===(aliases[id]||id))?.name||'Pilihan Perjalanan':'Pilihan Perjalanan';break}case 'keberangkatan':html=departurePage(id);title='Umroh Lampung 12 Hari — 9 Desember 2026';break;case 'tentang':html=about();title='Tentang Mitra';break;case 'galeri':html=gallery();title='Dokumentasi Jamaah';break;case 'artikel':html=id?article(id):pageHero('Jurnal & Inspirasi','Persiapan yang baik,<br><em>perjalanan lebih berarti.</em>','Catatan sederhana untuk membantu Anda memahami pilihan dan mempersiapkan perjalanan ibadah.')+`<section class="container section">${journalCards()}</section>`+cta();title=id?SITE.articles.find(a=>a.id===id)?.title||'Jurnal':'Jurnal & Inspirasi';break;case 'faq':html=pageHero('Pertanyaan Umum','Ada yang ingin<br><em>Anda tanyakan?</em>','Temukan jawaban awal, lalu konsultasikan kebutuhan perjalanan Anda bersama Mitra.')+`<section class="container section narrow">${faqs()}</section>`+cta();title='Pertanyaan Umum';break;case 'testimoni':html=testimonialsPage();title='Cerita Jamaah';break;case 'kontak':html=contact();title='Hubungi Kami';break;case 'privasi':html=pageHero('Kebijakan Privasi','Informasi Anda,<br><em>kami hargai.</em>')+`<section class="container section narrow policy"><h2>Situs dan percakapan Anda</h2><p>Website ini menyediakan informasi program serta tautan konsultasi. Tidak ada formulir pendaftaran, akun jamaah, atau pembayaran yang diproses langsung di website.</p><p>Tombol WhatsApp membuka layanan WhatsApp dengan pesan awal yang dapat diedit sebelum dikirim. Informasi yang Anda bagikan di sana mengikuti kebijakan layanan tersebut. Pencarian dan filter paket diproses di browser tanpa dikirim ke server aplikasi. Pilihan tema disimpan di perangkat melalui penyimpanan lokal browser agar tetap digunakan saat Anda kembali.</p><h2>Layanan pihak ketiga</h2><p>Google Fonts digunakan untuk tampilan huruf. Pratinjau dan pemutar video testimoni menggunakan layanan YouTube; pemutar dimuat saat Anda menekan tombol putar. Tautan YouTube, TikTok, WhatsApp, dan Google Maps membuka layanan pihak ketiga dengan kebijakan masing-masing.</p><h2>Hubungi Mitra</h2><p>Untuk pertanyaan mengenai informasi yang dibagikan dalam konsultasi, hubungi Tania Tombeng melalui 0823-1080-8355.</p></section>`;title='Kebijakan Privasi';break;default:html=notFound()}
$('#main').innerHTML=html;$('#main').className='route-enter';document.title=title+' — Umroh Amanah Samira';$$('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));$$('[data-wa]').forEach(a=>{a.href=wa(a.dataset.wa);a.target='_blank';a.rel='noopener'});$$('.header nav a').forEach(a=>{const active=a.hash==='#/'+page;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});closeMenu();if(page==='paket'&&!id)updatePackages();positionRouteContent();initVisualEffects();updateScrollUI();}
// The catalog opens at its choices, below the sticky navigation.
function positionRouteContent(){
 const {page,id}=route();
 const catalog=page==='paket'&&!id?$('.catalog-toolbar'):null;
 if(catalog)window.scrollTo({top:Math.max(0,window.scrollY+catalog.getBoundingClientRect().top-$('.header').getBoundingClientRect().height-22),behavior:'instant'});
 else window.scrollTo({top:0,behavior:'instant'});
}
document.addEventListener('click',e=>{
 const a=e.target.closest('a[href]');
 if(!a||e.defaultPrevented||e.button>0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;
 if(a.getAttribute('href')==='#main'){e.preventDefault();$('#main').focus({preventScroll:true});$('#main').scrollIntoView({block:'start',behavior:'instant'});return}
 if(a.getAttribute('href').startsWith('#/')&&a.getAttribute('href')===location.hash){
  e.preventDefault();closeMenu();positionRouteContent();
 }
});
function closeMenu(){$('#navigation').classList.remove('open');$('#menu').setAttribute('aria-expanded','false')}
$('#menu').addEventListener('click',()=>{const open=$('#navigation').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String(open));$('#menu').setAttribute('aria-label',open?'Tutup menu navigasi':'Buka menu navigasi')});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});
$('#main').addEventListener('click',e=>{const yt=e.target.closest('[data-youtube]');if(yt){const t=SITE.testimonials.find(t=>t.id===yt.dataset.youtube);if(!t)return;$$('[data-youtube-frame]').forEach(frame=>{if(frame.querySelector('iframe')){const previous=SITE.testimonials.find(t=>t.id===frame.dataset.youtubeFrame);frame.innerHTML=youtubePreview(previous)}});const frame=yt.closest('[data-youtube-frame]');const player=document.createElement('iframe');player.src='https://www.youtube-nocookie.com/embed/'+t.id+'?autoplay=1&rel=0&playsinline=1';player.title=t.title;player.allow='accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share';player.setAttribute('allowfullscreen','');player.referrerPolicy='strict-origin-when-cross-origin';frame.replaceChildren(player);return}const dep=e.target.closest('[data-departure-option]');if(dep){const index=Number(dep.dataset.departureOption),o=SITE.departure.options[index];$$('[data-departure-option]').forEach(b=>{b.classList.toggle('active',b===dep);b.setAttribute('aria-pressed',String(b===dep))});$('#departure-price').textContent='Rp'+money(o.price);$('#departure-label').textContent='Estimasi Paket '+o.name+' / jamaah';$('#departure-hotels').innerHTML=departureHotels(index);return}const f=e.target.closest('[data-filter]');if(f){activeCategory=f.dataset.filter;updatePackages();if(route().page==='paket')history.replaceState(null,'','#/paket'+(activeCategory==='semua'?'':'?jenis='+activeCategory));return}if(e.target.closest('[data-reset]')){activeCategory='semua';searchTerm='';if($('#package-search'))$('#package-search').value='';if(route().page==='paket')history.replaceState(null,'','#/paket');updatePackages();return}const v=e.target.closest('[data-package-option]');if(v){$$('[data-package-option]').forEach(x=>{x.classList.toggle('active',x===v);x.setAttribute('aria-pressed',String(x===v))});$('#detail-price').textContent='Rp'+money(Number(v.dataset.price));$('#detail-wa').href=wa(v.dataset.program+' — Paket '+v.dataset.packageOption);return}const l=e.target.closest('[data-lightbox]');if(l){const d=$('#lightbox');d.querySelector('img').src=l.dataset.lightbox;d.querySelector('img').alt=l.dataset.caption;d.querySelector('p').textContent=l.dataset.caption;d.showModal()}});
$('#main').addEventListener('play',e=>{if(e.target.tagName==='VIDEO')$$('.video-documentation video').forEach(v=>{if(v!==e.target)v.pause()})},true);
$('#main').addEventListener('input',e=>{if(e.target.id==='package-search'){searchTerm=e.target.value;updatePackages()}});
$('#main').addEventListener('submit',e=>{if(e.target.id==='journey-picker'){e.preventDefault();const chosen=$('#journey-type').value;location.hash=chosen==='semua'?'#/paket':programHref(programs.find(p=>p.id===chosen))}});
$('#lightbox .close-lightbox').addEventListener('click',()=>$('#lightbox').close());$('#lightbox').addEventListener('click',e=>{if(e.target===$('#lightbox'))$('#lightbox').close()});
// Motion never hides content before JavaScript initializes.
let visualObserver=null;
const motionSeen=new WeakSet();
function reduceMotion(){return typeof window.matchMedia==='function'&&window.matchMedia('(prefers-reduced-motion: reduce)').matches}
function initVisualEffects(){
 if(visualObserver)visualObserver.disconnect();
 if(reduceMotion()||typeof window.IntersectionObserver!=='function')return;
 visualObserver=new window.IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)continue;const el=entry.target;visualObserver.unobserve(el);if(motionSeen.has(el))continue;motionSeen.add(el);if(typeof el.animate==='function'){const index=[...el.parentElement.children].indexOf(el);el.animate([{opacity:0,transform:'translateY(22px)'},{opacity:1,transform:'translateY(0)'}],{duration:650,delay:Math.min(index%3*65,130),easing:'cubic-bezier(.2,.7,.2,1)',fill:'backwards'})}}},{threshold:.08,rootMargin:'0px 0px -25px 0px'});
 $$('.section-top,.package-card,.story-visual,.story-copy,.journey-steps>div,.award-card,.journal-card,.documentation-item,.hotel-panel,.facility-grid>li,.contact-card,.service-grid>div,.faq-intro,.contact-cta').forEach(el=>{if(!motionSeen.has(el))visualObserver.observe(el)});
}
function updateScrollUI(){const y=window.scrollY||0;const available=Math.max(document.documentElement.scrollHeight-(window.innerHeight||0),1);const line=$('.reading-progress span');if(line)line.style.transform='scaleX('+Math.min(y/available,1)+')';$('.header').classList.toggle('is-scrolled',y>30);const top=$('.back-to-top');if(top)top.hidden=y<650;}
let scrollFrame=false;
window.addEventListener('scroll',()=>{if(scrollFrame)return;scrollFrame=true;const schedule=window.requestAnimationFrame||((fn)=>fn());schedule(()=>{updateScrollUI();scrollFrame=false})},{passive:true});
$('.back-to-top').addEventListener('click',()=>window.scrollTo({top:0,behavior:reduceMotion()?'auto':'smooth'}));

$('#year').textContent=new Date().getFullYear();window.addEventListener('hashchange',render);window.addEventListener('load',positionRouteContent);render();
